1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>Swizzle Layout</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  /* Overrides for swizzle cell styling (base uses flex-direction:column; swizzle uses default) */
10	  .cell { color:#fff; text-shadow:0 1px 2px rgba(0,0,0,.25); line-height:normal; }
11	  .cell.rd { border-color:#222; border-width:3px; z-index:1; }
12	  .cell.prev { border-color:rgba(0,0,0,.2); border-width:2px; }
13	  .cell.dm { opacity:.18; }
14	  .cell.hov { box-shadow:none; }
15	  .panel h2 { margin-bottom:10px; }
16	
17	  /* Cycle bar */
18	  .cbar { display:flex; gap:5px; justify-content:center; align-items:center; margin-bottom:18px; flex-wrap:wrap; }
19	  .cb { width:34px; height:30px; border:1px solid var(--border); background:var(--surface); color:var(--text);
20	    cursor:pointer; border-radius:5px; font-size:13px; font-family:inherit; display:flex; align-items:center;
21	    justify-content:center; transition:all .12s; font-weight:500; }
22	  .cb:hover { background:#eef0f4; }
23	  .cb.on { background:var(--accent); border-color:var(--accent); color:#fff; }
24	  .play { width:34px; font-size:16px; }
25	
26	  /* Bank bar */
27	  .blab { font-size:11px; color:var(--dim); text-align:center; margin-top:12px; margin-bottom:3px; font-weight:600; }
28	  .bbar { display:flex; gap:3px; }
29	  .bs {
30	    flex:1; height:30px; border-radius:5px; display:flex; align-items:center; justify-content:center;
31	    font-size:11px; font-weight:700; color:#fff; border:2.5px solid transparent; transition:all .18s;
32	    text-shadow:0 1px 2px rgba(0,0,0,.2);
33	  }
34	  .bs.ac { border-color:#222; box-shadow:0 0 6px rgba(59,130,246,.3); }
35	  .bs.cf { border-color:#d32f2f; box-shadow:0 0 8px rgba(211,47,47,.4); }
36	  .bs.dm { opacity:.12; }
37	
38	  .st { text-align:center; margin-top:8px; font-size:13px; font-weight:600; min-height:20px; }
39	  .good { color:#2e7d32; } .bad { color:#c62828; }
40	
41	  /* Legend overrides */
42	  .leg { gap:0; }
43	  .swtch.brd { border:3px solid #222; background:#ccc; }
44	  .swtch.brd-prev { border:2px solid rgba(0,0,0,.2); background:#ccc; }
45	  .swtch.faded { background:#ccc; opacity:.18; }
46	  .leg-row+.leg-row { margin-top:6px; }
47	
48	  /* ── Timeline ── */
49	  .tl-wrap { max-width:1100px; margin:24px auto 0; }
50	  .tl-head { font-size:15px; font-weight:700; text-align:center; margin-bottom:14px; }
51	  .tl-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
52	  .tl-box { background:var(--surface); border-radius:10px; padding:14px; min-height:300px; border:1px solid var(--border);
53	    box-shadow:0 1px 3px rgba(0,0,0,.06); }
54	  .tl-box h3 { font-size:13px; font-weight:700; text-align:center; margin-bottom:10px; color:var(--dim); }
55	  .tl-row { display:flex; align-items:center; gap:6px; margin-bottom:4px; cursor:pointer; border-radius:6px;
56	    padding:3px 4px; transition:background .12s; }
57	  .tl-row:hover { background:#f0f1f4; }
58	  .tl-row.sel { background:#e8edf5; }
59	  .tl-row.done { background:#f0f7f0; }
60	  .tl-cyc { font-size:11px; font-weight:700; color:var(--dim); width:52px; text-align:right; flex-shrink:0; }
61	  .tl-banks { display:flex; gap:2px; flex:1; }
62	  .tl-b {
63	    flex:1; height:26px; border-radius:4px; display:flex; align-items:center; justify-content:center;
64	    font-size:10px; font-weight:700; color:#fff; text-shadow:0 1px 1px rgba(0,0,0,.2);
65	    border:2px solid transparent;
66	  }
67	  .tl-b.on { border-color:#222; }
68	  .tl-b.empty { background:#e8e8e8 !important; color:#bbb; text-shadow:none; }
69	  .tl-cnt { font-size:11px; color:var(--dim); width:38px; text-align:left; flex-shrink:0; font-weight:600; }
70	  .tl-sum { text-align:center; margin-top:10px; font-size:13px; font-weight:600; }
71	
72	  @media(max-width:700px) { .tl-grid { grid-template-columns:1fr; } }
73	</style>
74	</head>
75	<body>
76	
77	<h1>Swizzle Layout — 8×8</h1>
78	<div class="sub">mapped_col = logical_col XOR row &nbsp;|&nbsp; 8×8 matrix, 1 element = 1 bank</div>
79	
80	<div class="controls">
81	  <div><span class="lbl">Read</span>
82	    <div class="bg" id="rt">
83	      <button class="btn on" data-v="col">Read Col</button>
84	      <button class="btn" data-v="row">Read Row</button>
85	    </div>
86	  </div>
87	  <div><span class="lbl">Index</span><div class="bg" id="ri"></div></div>
88	</div>
89	
90	<div class="panels">
91	  <svg class="arrow-svg" id="arrow"></svg>
92	  <div class="panel"><h2>Without Swizzle</h2>
93	    <div class="grid" id="g0"></div><div class="blab">Bank Activity</div>
94	    <div class="bbar" id="b0"></div><div class="st" id="s0"></div>
95	  </div>
96	  <div class="panel"><h2>With Swizzle (XOR)</h2>
97	    <div class="grid" id="g1"></div><div class="blab">Bank Activity</div>
98	    <div class="bbar" id="b1"></div><div class="st" id="s1"></div>
99	  </div>
100	</div>
101	<div class="leg" id="lg"></div>
102	
103	<div class="tl-wrap">
104	  <div class="tl-head">Cycle-by-Cycle Reads</div>
105	  <div class="cbar" id="cb"></div>
106	  <div class="tl-grid">
107	    <div class="tl-box"><h3>Without Swizzle</h3><div id="tl0"></div><div class="tl-sum" id="ts0"></div></div>
108	    <div class="tl-box"><h3>With Swizzle (XOR)</h3><div id="tl1"></div><div class="tl-sum" id="ts1"></div></div>
109	  </div>
110	</div>
111	
112	<script>
113	const BK = ['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
114	const BANKS = 8;
115	const ROWS=8, COLS=8;
116	const ST = { t:'col', i:-1, c:0, pl:false, tm:null };
117	
118	// Physical bank = col XOR row; 8 banks, 1 element = 1 bank
119	const bank = (r,c,sw) => sw ? (c^r) : c;
120	// Physical column position for a logical column in a given row
121	const physCol = (r,c,sw) => sw ? (c^r) : c;
122	// Logical column at a physical position in a given row
123	const logAtPhys = (r,p,sw) => sw ? (p^r) : p;
124	
125	function getCells() {
126	  if(ST.i<0) return [];
127	  if(ST.t==='col') return Array.from({length:ROWS},(_,j) => ({r:j,c:ST.i}));
128	  return Array.from({length:COLS},(_,j) => ({r:ST.i,c:j}));
129	}
130	
131	function getCycles(cl,sw) {
132	  if(cl.length===0) return [];
133	  const g=new Map();
134	  for(const x of cl){const b=bank(x.r,x.c,sw);if(!g.has(b))g.set(b,[]);g.get(b).push({...x,b});}
135	  const mx=Math.max(...[...g.values()].map(v=>v.length));
136	  const out=[];
137	  for(let ci=0;ci<mx;ci++){const rd=[];for(const[,v]of g)if(ci<v.length)rd.push(v[ci]);out.push(rd);}
138	  return out;
139	}
140	
141	function draw() {
142	  const cl=getCells(), rs=new Set(cl.map(x=>x.r+','+x.c));
143	  const cy=[getCycles(cl,false),getCycles(cl,true)], mc=Math.max(cy[0].length,cy[1].length);
144	
145	  // ── Cycle bar (inside timeline section) ──
146	  const cb=document.getElementById('cb'); cb.innerHTML='';
147	  if(mc>0){
148	    cb.appendChild(Object.assign(mk('span'),{style:'font-size:11px;color:var(--dim);margin-right:6px',textContent:'Click to show reads per cycle'}));
149	    const pb=mk('button','cb play'); pb.textContent=ST.pl?'⏸':'▶'; pb.onclick=doPlay; cb.appendChild(pb);
150	    cb.appendChild(Object.assign(mk('span'),{style:'font-size:13px;color:var(--dim);margin:0 6px',textContent:'Cycle:'}));
151	    const allBtn=mk('button','cb'+(ST.c===0?' on':'')); allBtn.textContent='All'; allBtn.onclick=()=>{ST.c=0;draw();}; cb.appendChild(allBtn);
152	    for(let i=1;i<=mc;i++){const b=mk('button','cb'+(ST.c===i?' on':'')); b.textContent=i; b.onclick=(v=>()=>{ST.c=v;draw();})(i); cb.appendChild(b);}
153	  }
154	
155	  // ── Panels (grid + bank bar) ──
156	  for(let sw=0;sw<2;sw++){
157	    const swz=sw===1, myc=cy[sw], tot=myc.length;
158	
159	    // Determine current-cycle vs previous-cycle reads for grid highlights
160	    let cur=rs, prev=new Set();
161	    if(ST.c>0 && ST.c<=tot) {
162	      cur=new Set(myc[ST.c-1].map(x=>x.r+','+x.c));
163	      for(let ci=0;ci<ST.c-1;ci++) for(const x of myc[ci]) prev.add(x.r+','+x.c);
164	    } else if(ST.c>0 && ST.c>tot) {
165	      cur=new Set(); for(const x of cl) prev.add(x.r+','+x.c);
166	    }
167	
168	    // Bank usage: current cycle when selected, empty if past last cycle, full read set for "All"
169	    const ab=new Map();
170	    const bsrc=ST.c===0?cl:(ST.c<=tot?myc[ST.c-1]:[]);
171	    for(const x of bsrc){const b='b'in x?x.b:bank(x.r,x.c,swz);ab.set(b,(ab.get(b)||0)+1);}
172	
173	    // Grid — show PHYSICAL layout (x-axis = physical column position)
174	    // Cell color = bank (physCol % 8), cell value = logical column
175	    const g=document.getElementById('g'+sw); g.innerHTML='';
176	    g.style.gridTemplateColumns='24px repeat('+COLS+',1fr)';
177	    g.appendChild(mk('div','hdr'));
178	    for(let p=0;p<COLS;p++){const h=mk('div','hdr');h.textContent='b'+(p%BANKS);g.appendChild(h);}
179	    for(let r=0;r<ROWS;r++){
180	      const l=mk('div','rl');l.textContent='r'+r;g.appendChild(l);
181	      for(let p=0;p<COLS;p++){
182	        const lc=logAtPhys(r,p,swz);
183	        const d=mk('div','cell');d.textContent=lc;d.style.background=BK[p%BANKS];
184	        d.dataset.r=r;d.dataset.c=lc;
185	        const k=r+','+lc;
186	        if(cur.has(k))d.classList.add('rd');
187	        else if(prev.has(k))d.classList.add('prev');
188	        else if(rs.size>0&&!rs.has(k))d.classList.add('dm');
189	        g.appendChild(d);
190	      }
191	    }
192	
193	    // Bank bar
194	    const bb=document.getElementById('b'+sw);bb.innerHTML='';
195	    for(let b=0;b<BANKS;b++){
196	      const d=mk('div','bs');d.style.background=BK[b];const cnt=ab.get(b)||0;
197	      if(rs.size===0){d.textContent='B'+b;}
198	      else if(cnt>1){d.textContent='B'+b+' \u00d7'+cnt;d.classList.add('ac','cf');}
199	      else if(cnt===1){d.textContent='B'+b;d.classList.add('ac');}
200	      else{d.textContent='B'+b;d.classList.add('dm');}
201	      bb.appendChild(d);
202	    }
203	
204	    // Stats — cycle-aware
205	    const se=document.getElementById('s'+sw);
206	    if(rs.size===0) se.innerHTML='';
207	    else if(ST.c===0) {
208	      // "All" mode: show total summary with conflict info
209	      if(tot<=1) se.innerHTML='<span class="good">'+ab.size+'/'+BANKS+' banks · 1 cycle · No conflicts</span>';
210	      else se.innerHTML='<span class="bad">'+ab.size+'/'+BANKS+' banks · '+tot+' cycles · '+tot+'-way conflict</span>';
211	    } else {
212	      // Single cycle: show current cycle bank usage
213	      se.innerHTML='<span style="color:var(--dim)">Cycle '+ST.c+': '+ab.size+'/'+BANKS+' banks active</span>';
214	    }
215	  }
216	
217	  // ── Timeline ──
218	  drawTimeline(cy, mc);
219	}
220	
221	function drawTimeline(cy, mc) {
222	  for(let sw=0;sw<2;sw++){
223	    const myc=cy[sw], tot=myc.length;
224	    const el=document.getElementById('tl'+sw); el.innerHTML='';
225	    const ts=document.getElementById('ts'+sw);
226	    if(mc===0){ ts.innerHTML='<span style="color:var(--dim)">Select a read index to see cycles</span>'; continue; }
227	
228	    for(let ci=0;ci<mc;ci++){
229	      // Hide timeline rows after selected cycle
230	      if(ST.c>0 && ci+1>ST.c) continue;
231	      let cls='tl-row';
232	      if(ST.c>0 && ci+1===ST.c) cls+=' sel';
233	      else if(ST.c>0 && ci+1<ST.c && ci<tot) cls+=' done';
234	      const row=mk('div',cls);
235	      row.onclick=(v=>()=>{ST.c=v;draw();})(ci+1);
236	
237	      // Label
238	      const lbl=mk('div','tl-cyc'); lbl.textContent='Cycle '+(ci+1); row.appendChild(lbl);
239	
240	      // Bank slots
241	      const bbar=mk('div','tl-banks');
242	      let active=0;
243	      for(let b=0;b<BANKS;b++){
244	        const slot=mk('div','tl-b');
245	        const rds=[];if(ci<tot) for(const rd of myc[ci]) if(rd.b===b) rds.push(rd);
246	        if(rds.length>0){
247	          slot.style.background=BK[b]; slot.textContent=rds.map(x=>x.c).join(',');
248	          if(rds.length>1) slot.style.fontSize='8px';
249	          if(ST.c===ci+1) slot.classList.add('on');
250	          active++;
251	        } else {
252	          slot.classList.add('empty'); slot.textContent='\u00b7';
253	        }
254	        bbar.appendChild(slot);
255	      }
256	      row.appendChild(bbar);
257	
258	      // Per-row count
259	      const cnt=mk('div','tl-cnt');
260	      if(ci<tot) cnt.textContent=active+'/'+BANKS;
261	      else cnt.textContent='\u2014';
262	      row.appendChild(cnt);
263	
264	      el.appendChild(row);
265	    }
266	
267	    if(tot<=1) ts.innerHTML='<span class="good">1 cycle — all '+BANKS+' banks used simultaneously</span>';
268	    else ts.innerHTML='<span class="bad">'+tot+' cycles — only '+(tot>0?myc[0].length:0)+'/'+BANKS+' banks per cycle</span>';
269	  }
270	}
271	
272	function mk(t,c){const d=document.createElement(t);if(c)d.className=c;return d;}
273	
274	function doPlay(){
275	  if(ST.pl){clearInterval(ST.tm);ST.pl=false;draw();return;}
276	  const mc=Math.max(getCycles(getCells(),false).length,getCycles(getCells(),true).length);
277	  ST.c=1;ST.pl=true;draw();
278	  ST.tm=setInterval(()=>{ST.c++;if(ST.c>mc){ST.c=0;clearInterval(ST.tm);ST.pl=false;}draw();},700);
279	}
280	
281	function rebuildIndex(){
282	  const ig=document.getElementById('ri'); ig.innerHTML='';
283	  const max=ST.t==='col'?COLS:ROWS;
284	  if(ST.i>=max) ST.i=-1;
285	  const nb=mk('button','btn'+(ST.i<0?' on':''));nb.textContent='None';
286	  nb.onclick=()=>{ST.i=-1;ST.c=0;ig.querySelectorAll('.btn').forEach(x=>x.classList.remove('on'));nb.classList.add('on');draw();};
287	  ig.appendChild(nb);
288	  for(let i=0;i<max;i++){
289	    const b=mk('button','btn'+(ST.i===i?' on':''));b.textContent=i;
290	    b.onclick=(v=>()=>{ST.i=v;ST.c=0;ig.querySelectorAll('.btn').forEach(x=>x.classList.remove('on'));b.classList.add('on');draw();})(i);
291	    ig.appendChild(b);
292	  }
293	}
294	
295	(function init(){
296	  // Read type
297	  document.getElementById('rt').onclick=e=>{
298	    const b=e.target.closest('.btn');if(!b)return;
299	    ST.t=b.dataset.v;ST.c=0;
300	    document.querySelectorAll('#rt .btn').forEach(x=>x.classList.remove('on'));b.classList.add('on');
301	    rebuildIndex();draw();
302	  };
303	  // Index buttons
304	  rebuildIndex();
305	  // Legend
306	  const lg=document.getElementById('lg');
307	  // Bank colors (top row)
308	  const r1=mk('div','leg-row');
309	  for(let i=0;i<BANKS;i++){const d=mk('div','li'),w=mk('div','swtch');w.style.background=BK[i];d.appendChild(w);d.appendChild(document.createTextNode('Bank '+i));r1.appendChild(d);}
310	  lg.appendChild(r1);
311	  // Encoding + cell meaning (bottom row)
312	  const r2=mk('div','leg-row');
313	  const enc=[['brd','Current read'],['brd-prev','Earlier cycle'],['faded','Not read']];
314	  for(const[cls,txt]of enc){const d=mk('div','li'),w=mk('div','swtch '+cls);d.appendChild(w);d.appendChild(document.createTextNode(txt));r2.appendChild(d);}
315	  r2.appendChild(mk('div','leg-sep'));
316	  const cv=mk('div','li');cv.textContent='Cell value = logical column';r2.appendChild(cv);
317	  r2.appendChild(mk('div','leg-sep'));
